'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import { crisp, dashedLine, makeScale, niceTicks, prepareCanvas, readTokens } from '../../canvas';
import { formatAxisTime, formatMoney, formatPercent, formatTime } from '../../format';
import { useElementSize } from '../../hooks';
import { useInstrument } from '../../theme/theme-provider';
import type { Instrument } from '../../types';
import { cn, toArray } from '../../utils';

export interface EquityPoint {
  time: number;
  /** Account equity at this moment. */
  equity: number;
}

export interface PnlChartProps {
  points: EquityPoint[];
  instrument?: Partial<Instrument>;
  height?: number;
  /** Baseline to measure P&L against. Defaults to the first point. */
  startingEquity?: number;
  /** Shade peak-to-trough drawdown beneath the curve. */
  showDrawdown?: boolean;
  /** Dashed rule at the starting equity. */
  showBaseline?: boolean;
  crosshair?: boolean;
  className?: string;
}

const TOKENS = [
  '--up',
  '--down',
  '--up-line',
  '--down-line',
  '--chart-grid',
  '--chart-axis',
  '--chart-crosshair',
  '--muted-foreground',
] as const;

const AXIS_WIDTH = 62;
const TIME_AXIS_HEIGHT = 18;
const PAD = 8;

/** Running maximum, so drawdown is measured from the peak rather than the start. */
function runningPeak(values: number[]): number[] {
  let peak = -Infinity;
  return values.map((v) => (peak = Math.max(peak, v)));
}

/**
 * Equity curve with drawdown.
 *
 * The curve is coloured against the starting equity, but the shaded region is
 * measured from the running peak — those are different questions. "Am I up on
 * the day" and "how far below my high-water mark am I" both matter, and a
 * chart that only answers the first lets a long bleed off a peak look like a
 * healthy green line.
 */
export function PnlChart({
  points,
  instrument,
  height = 220,
  startingEquity,
  showDrawdown = true,
  showBaseline = true,
  crosshair = true,
  className,
}: PnlChartProps) {
  const inst = useInstrument(instrument);
  const [wrapRef, size] = useElementSize<HTMLDivElement>();
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const [hover, setHover] = useState<{ index: number; x: number } | null>(null);

  const width = size.width;

  const series = toArray(points);

  const model = useMemo(() => {
    if (series.length < 2) return null;
    const equity = series.map((p) => p.equity);
    const base = startingEquity ?? equity[0];
    const peaks = runningPeak(equity);
    const maxDrawdown = Math.min(...equity.map((v, i) => (v - peaks[i]) / peaks[i]));
    return {
      base,
      peaks,
      lo: Math.min(...equity, base),
      hi: Math.max(...equity, base),
      last: equity[equity.length - 1],
      maxDrawdown,
    };
  }, [series, startingEquity]);

  useEffect(() => {
    const canvas = canvasRef.current;
    const wrap = wrapRef.current;
    if (!canvas || !wrap || !model || width < 2) return;

    const ctx = prepareCanvas(canvas, width, height);
    if (!ctx) return;
    const c = readTokens(wrap, TOKENS);

    const left = PAD;
    const right = width - AXIS_WIDTH;
    const top = PAD;
    const bottom = height - TIME_AXIS_HEIGHT;

    const pad = (model.hi - model.lo) * 0.08 || Math.abs(model.hi) * 0.01 || 1;
    const y = makeScale(model.lo - pad, model.hi + pad, bottom, top);
    const x = makeScale(0, series.length - 1, left, right);

    ctx.font = '10px ui-monospace, monospace';
    ctx.textBaseline = 'middle';

    for (const tick of niceTicks(model.lo - pad, model.hi + pad, 4)) {
      const ty = y(tick);
      if (ty < top - 1 || ty > bottom + 1) continue;
      ctx.strokeStyle = c['--chart-grid'];
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(left, crisp(ty));
      ctx.lineTo(right, crisp(ty));
      ctx.stroke();
      ctx.fillStyle = c['--chart-axis'];
      ctx.textAlign = 'left';
      ctx.fillText(formatMoney(tick, inst.currency, 0), right + 6, ty);
    }

    const labelEvery = Math.max(1, Math.ceil(series.length / Math.max(1, Math.floor((right - left) / 70))));
    ctx.textAlign = 'center';
    ctx.fillStyle = c['--chart-axis'];
    for (let i = series.length - 1; i >= 0; i -= labelEvery) {
      ctx.fillText(formatAxisTime(series[i].time), x(i), bottom + TIME_AXIS_HEIGHT / 2);
    }

    const up = model.last >= model.base;
    const stroke = up ? c['--up'] : c['--down'];

    if (showDrawdown) {
      // Between the running peak and the curve: the region is the loss from
      // the high-water mark, which is why it is always drawn in the down tone.
      ctx.beginPath();
      series.forEach((_, i) => {
        const px = x(i);
        const py = y(model.peaks[i]);
        i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
      });
      for (let i = series.length - 1; i >= 0; i--) {
        ctx.lineTo(x(i), y(series[i].equity));
      }
      ctx.closePath();
      ctx.fillStyle = c['--down-line'];
      ctx.globalAlpha = 0.22;
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    if (showBaseline) {
      ctx.strokeStyle = c['--chart-crosshair'];
      ctx.lineWidth = 1;
      dashedLine(ctx, left, crisp(y(model.base)), right, crisp(y(model.base)), [3, 4]);
    }

    const fill = ctx.createLinearGradient(0, top, 0, bottom);
    fill.addColorStop(0, up ? c['--up-line'] : c['--down-line']);
    fill.addColorStop(1, 'transparent');
    ctx.save();
    ctx.beginPath();
    series.forEach((p, i) => {
      const px = x(i);
      const py = y(p.equity);
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    });
    ctx.lineTo(x(series.length - 1), bottom);
    ctx.lineTo(x(0), bottom);
    ctx.closePath();
    ctx.globalAlpha = 0.35;
    ctx.fillStyle = fill;
    ctx.fill();
    ctx.restore();

    ctx.beginPath();
    series.forEach((p, i) => {
      const px = x(i);
      const py = y(p.equity);
      i === 0 ? ctx.moveTo(px, py) : ctx.lineTo(px, py);
    });
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1.75;
    ctx.lineJoin = 'round';
    ctx.stroke();

    if (crosshair && hover) {
      const px = x(hover.index);
      ctx.strokeStyle = c['--chart-crosshair'];
      dashedLine(ctx, crisp(px), top, crisp(px), bottom, [3, 3]);
      ctx.fillStyle = stroke;
      ctx.beginPath();
      ctx.arc(px, y(series[hover.index].equity), 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }, [model, series, width, height, showDrawdown, showBaseline, crosshair, hover, inst.currency, wrapRef]);

  if (!model) {
    return <div className="text-muted-foreground p-5 text-center text-xs">Not enough history</div>;
  }

  const hovered = hover ? series[hover.index] : undefined;
  const hoveredPnl = hovered ? hovered.equity - model.base : 0;

  return (
    <div
      ref={wrapRef}
      className={cn('relative w-full', className)}
      style={{ height }}
      onPointerMove={(e) => {
        if (!crosshair) return;
        const rect = e.currentTarget.getBoundingClientRect();
        const px = e.clientX - rect.left;
        const inner = Math.max(1, rect.width - AXIS_WIDTH - PAD);
        const index = Math.min(
          series.length - 1,
          Math.max(0, Math.round(((px - PAD) / inner) * (series.length - 1))),
        );
        setHover({ index, x: px });
      }}
      onPointerLeave={() => setHover(null)}
    >
      <canvas ref={canvasRef} className="block size-full" />
      {hovered && hover && (
        <div
          className="bg-popover text-popover-foreground pointer-events-none absolute top-2 z-20 flex flex-col gap-0.5 rounded-md border p-2 font-mono text-[10px] tabular-nums shadow-lg"
          style={{
            left: hover.x > width - 150 ? undefined : hover.x + 12,
            right: hover.x > width - 150 ? width - hover.x + 12 : undefined,
          }}
        >
          <div className="flex justify-between gap-4">
            <span className="text-muted-foreground">{formatTime(hovered.time).slice(0, 5)}</span>
            <span className="font-semibold">{formatMoney(hovered.equity, inst.currency)}</span>
          </div>
          <div className="flex justify-between gap-4">
            <span className="text-muted-foreground">P&amp;L</span>
            <span className={cn('font-semibold', hoveredPnl >= 0 ? 'text-up' : 'text-down')}>
              {formatMoney(hoveredPnl, inst.currency)} {formatPercent(hoveredPnl / model.base)}
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

/** Canvas plumbing shared by the chart components. */

export interface ChartPadding {
  top: number;
  right: number;
  bottom: number;
  left: number;
}

/**
 * Sizes the backing store to the device pixel ratio and returns a context
 * already scaled to CSS pixels, so drawing code can use layout units and still
 * get crisp 1px gridlines on a HiDPI screen.
 */
export function prepareCanvas(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
): CanvasRenderingContext2D | null {
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const w = Math.max(1, Math.floor(width * dpr));
  const h = Math.max(1, Math.floor(height * dpr));
  if (canvas.width !== w) canvas.width = w;
  if (canvas.height !== h) canvas.height = h;

  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, width, height);
  return ctx;
}

/**
 * Resolves CSS custom properties against a live element. The charts paint on
 * canvas, which cannot inherit `var(--tu-up)`, so they read the tokens once
 * per draw and stay in sync with whatever theme the host applied.
 */
export function readTokens<K extends string>(
  el: Element,
  names: readonly K[],
): Record<K, string> {
  const style = getComputedStyle(el);
  const out = {} as Record<K, string>;
  for (const name of names) {
    out[name] = style.getPropertyValue(name).trim() || '#888';
  }
  return out;
}

/** Linear scale from a data domain to a pixel range. */
export function makeScale(
  domainMin: number,
  domainMax: number,
  rangeMin: number,
  rangeMax: number,
) {
  const span = domainMax - domainMin || 1;
  const pixels = rangeMax - rangeMin;
  const scale = (value: number) => rangeMin + ((value - domainMin) / span) * pixels;
  scale.invert = (pixel: number) => domainMin + ((pixel - rangeMin) / pixels) * span;
  return scale;
}

/**
 * "Nice" tick values at human-readable intervals (1, 2, 5 x 10^n) so the price
 * axis reads 42.50 / 43.00 / 43.50 instead of 42.37 / 42.91 / 43.45.
 */
export function niceTicks(min: number, max: number, target = 5): number[] {
  if (!Number.isFinite(min) || !Number.isFinite(max) || max <= min) return [min];
  const raw = (max - min) / target;
  const magnitude = Math.pow(10, Math.floor(Math.log10(raw)));
  const normalized = raw / magnitude;
  const step =
    (normalized >= 5 ? 10 : normalized >= 2 ? 5 : normalized >= 1 ? 2 : 1) * magnitude;

  const ticks: number[] = [];
  for (let t = Math.ceil(min / step) * step; t <= max + step * 1e-6; t += step) {
    ticks.push(Number(t.toFixed(10)));
  }
  return ticks;
}

/** Snaps a coordinate to a half-pixel so a 1px stroke lands on one pixel row. */
export function crisp(value: number): number {
  return Math.round(value) + 0.5;
}

/** Fills a rounded rect; `ctx.roundRect` is still patchy in older Safari. */
export function fillRoundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  const radius = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.lineTo(x + w - radius, y);
  ctx.quadraticCurveTo(x + w, y, x + w, y + radius);
  ctx.lineTo(x + w, y + h - radius);
  ctx.quadraticCurveTo(x + w, y + h, x + w - radius, y + h);
  ctx.lineTo(x + radius, y + h);
  ctx.quadraticCurveTo(x, y + h, x, y + h - radius);
  ctx.lineTo(x, y + radius);
  ctx.quadraticCurveTo(x, y, x + radius, y);
  ctx.fill();
}

/** Dashed horizontal rule used for the last-price and crosshair lines. */
export function dashedLine(
  ctx: CanvasRenderingContext2D,
  x1: number,
  y1: number,
  x2: number,
  y2: number,
  dash: number[] = [3, 3],
) {
  ctx.save();
  ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

import type { Direction } from './types';

/**
 * Formatting helpers. Every number shown in a trading UI is formatted the same
 * way twice: fixed decimals so digits line up in a tabular-nums column, and an
 * explicit sign where direction matters.
 */

const cache = new Map<string, Intl.NumberFormat>();

function nf(min: number, max: number, extra?: Intl.NumberFormatOptions) {
  const key = `${min}:${max}:${extra ? JSON.stringify(extra) : ''}`;
  let f = cache.get(key);
  if (!f) {
    f = new Intl.NumberFormat('en-US', {
      minimumFractionDigits: min,
      maximumFractionDigits: max,
      ...extra,
    });
    cache.set(key, f);
  }
  return f;
}

/** `1234.5` at precision 2 -> `"1,234.50"`. */
export function formatPrice(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  return nf(precision, precision).format(value);
}

/** Quantity: grouped, trailing zeros trimmed. */
export function formatQuantity(value: number, precision = 0): string {
  if (!Number.isFinite(value)) return '--';
  return nf(0, precision).format(value);
}

/** `1250000` -> `"1.25M"`. Keeps size columns to four glyphs. */
export function formatCompact(value: number, digits = 2): string {
  if (!Number.isFinite(value)) return '--';
  const abs = Math.abs(value);
  const sign = value < 0 ? '-' : '';
  const units: Array<[number, string]> = [
    [1e12, 'T'],
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'K'],
  ];
  for (const [scale, suffix] of units) {
    if (abs >= scale) {
      const scaled = abs / scale;
      // Keep three significant digits: 1.25M, 12.5M, 125M.
      const d = scaled >= 100 ? 0 : scaled >= 10 ? 1 : digits;
      return `${sign}${nf(0, d).format(scaled)}${suffix}`;
    }
  }
  return `${sign}${nf(0, abs < 1 ? digits : 0).format(abs)}`;
}

/** `0.0421` -> `"+4.21%"`. Input is a ratio, not percentage points. */
export function formatPercent(ratio: number, precision = 2, signed = true): string {
  if (!Number.isFinite(ratio)) return '--';
  const pct = ratio * 100;
  const sign = signed && pct > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(pct)}%`;
}

/** Absolute change with a forced sign so gains and losses align. */
export function formatSigned(value: number, precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value > 0 ? '+' : '';
  return `${sign}${nf(precision, precision).format(value)}`;
}

/** `hh:mm:ss` in local time - the tape's only useful resolution. */
export function formatTime(time: number | Date, withMillis = false): string {
  const d = time instanceof Date ? time : new Date(time);
  const base = d.toTimeString().slice(0, 8);
  if (!withMillis) return base;
  return `${base}.${String(d.getMilliseconds()).padStart(3, '0')}`;
}

/** Axis-friendly timestamp: drops seconds, adds the date when it changes. */
export function formatAxisTime(time: number, showDate = false): string {
  const d = new Date(time);
  const hhmm = d.toTimeString().slice(0, 5);
  if (!showDate) return hhmm;
  return `${d.getMonth() + 1}/${d.getDate()}`;
}

/** Signed money, e.g. `-$1,204.50`. */
export function formatMoney(value: number, currency = '$', precision = 2): string {
  if (!Number.isFinite(value)) return '--';
  const sign = value < 0 ? '-' : '';
  return `${sign}${currency}${nf(precision, precision).format(Math.abs(value))}`;
}

/** Direction of `value` relative to `reference` (default zero). */
export function directionOf(value: number, reference = 0): Direction {
  if (!Number.isFinite(value) || value === reference) return 'flat';
  return value > reference ? 'up' : 'down';
}

/** The `tu-up` / `tu-down` / `tu-flat` class for a direction. */
export function directionClass(direction: Direction): string {
  return `tu-${direction}`;
}

/** `+` / `-` glyphs used by DeltaBadge and the tape. */
export function directionArrow(direction: Direction): string {
  return direction === 'up' ? '▲' : direction === 'down' ? '▼' : '–';
}

/** Round to the instrument's tick so UI-entered prices are always valid. */
export function roundToTick(price: number, tickSize: number): number {
  if (!tickSize || tickSize <= 0) return price;
  const ticks = Math.round(price / tickSize);
  // Re-round after dividing to shake off float dust (0.1 * 3 = 0.30000000000000004).
  const decimals = decimalsOf(tickSize);
  return Number((ticks * tickSize).toFixed(decimals));
}

/** Decimal places implied by a tick size: `0.01` -> 2, `0.5` -> 1, `5` -> 0. */
export function decimalsOf(tickSize: number): number {
  if (!Number.isFinite(tickSize) || tickSize <= 0) return 2;
  const s = tickSize.toString();
  if (s.includes('e-')) return Number(s.split('e-')[1]);
  const dot = s.indexOf('.');
  return dot === -1 ? 0 : s.length - dot - 1;
}

/** Shared domain types. Deliberately plain so any feed can map onto them. */

export type Side = 'buy' | 'sell';
export type Direction = 'up' | 'down' | 'flat';

/** One OHLCV bar. `time` is epoch milliseconds at the bar's open. */
export interface Candle {
  time: number;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

/** A single price level in the book. */
export interface BookLevel {
  price: number;
  size: number;
}

export interface OrderBookSnapshot {
  /** Highest price first. */
  bids: BookLevel[];
  /** Lowest price first. */
  asks: BookLevel[];
}

export interface Trade {
  id: string;
  time: number;
  price: number;
  size: number;
  /** Aggressor side: `buy` means it lifted the offer. */
  side: Side;
}

export interface Quote {
  symbol: string;
  name?: string;
  last: number;
  /** Previous session close, used for the day change. */
  prevClose: number;
  bid?: number;
  ask?: number;
  dayHigh?: number;
  dayLow?: number;
  volume?: number;
  /** Optional intraday series for an inline sparkline. */
  history?: number[];
}

export interface Position {
  symbol: string;
  /** Signed: negative is short. */
  quantity: number;
  avgPrice: number;
  markPrice: number;
}

export type OrderType = 'market' | 'limit' | 'stop' | 'stop-limit';
export type OrderStatus = 'working' | 'filled' | 'partial' | 'cancelled' | 'rejected';

export interface OrderDraft {
  symbol: string;
  side: Side;
  type: OrderType;
  quantity: number;
  /** Required for limit / stop-limit. */
  limitPrice?: number;
  /** Required for stop / stop-limit. */
  stopPrice?: number;
  timeInForce: TimeInForce;
}

export type TimeInForce = 'day' | 'gtc' | 'ioc' | 'fok';

export interface Order extends OrderDraft {
  id: string;
  time: number;
  status: OrderStatus;
  filledQuantity: number;
  avgFillPrice?: number;
}

/** Price/size formatting rules for an instrument. */
export interface Instrument {
  symbol: string;
  name?: string;
  /** Decimal places for price. */
  pricePrecision: number;
  /** Minimum price increment. */
  tickSize: number;
  /** Decimal places for quantity. */
  sizePrecision?: number;
  /** Quote-currency symbol, e.g. "$". */
  currency?: string;
}

/**
 * One execution. Distinct from an `Order`: an order is an instruction, a fill
 * is what actually happened to it, and a single order can produce many fills
 * at different prices. Reconciliation, cost basis and fee accounting all work
 * off fills, never off orders.
 */
export interface Fill {
  id: string;
  /** The order this execution belongs to, for grouping a partial sequence. */
  orderId?: string;
  symbol: string;
  time: number;
  side: Side;
  quantity: number;
  price: number;
  /** Commission or exchange fee, in the quote currency. Negative is a rebate. */
  fee?: number;
  /** `maker` rested and was hit; `taker` crossed the spread. Drives the fee. */
  liquidity?: 'maker' | 'taker';
  venue?: string;
}

'use client';

import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import type { Direction } from './types';

/**
 * Measures an element with ResizeObserver. Canvas charts need real pixel
 * dimensions, and in a resizable terminal layout those change constantly.
 */
export function useElementSize<T extends HTMLElement>() {
  const ref = useRef<T | null>(null);
  const [size, setSize] = useState({ width: 0, height: 0 });

  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;

    const read = () => {
      const rect = el.getBoundingClientRect();
      setSize((prev) =>
        // Sub-pixel churn would re-render on every scroll of a parent.
        Math.abs(prev.width - rect.width) < 0.5 &&
        Math.abs(prev.height - rect.height) < 0.5
          ? prev
          : { width: rect.width, height: rect.height },
      );
    };

    read();
    if (typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(read);
    ro.observe(el);
    return () => ro.disconnect();
  }, []);

  return [ref, size] as const;
}

/**
 * Reports which way a value last moved and clears back to `flat` after
 * `duration`, so a price cell can flash green/red on each tick.
 */
export function usePriceFlash(value: number, duration = 420): Direction {
  const previous = useRef(value);
  const [flash, setFlash] = useState<Direction>('flat');

  useEffect(() => {
    const prev = previous.current;
    previous.current = value;
    if (!Number.isFinite(value) || !Number.isFinite(prev) || value === prev) return;

    setFlash(value > prev ? 'up' : 'down');
    const t = setTimeout(() => setFlash('flat'), duration);
    return () => clearTimeout(t);
  }, [value, duration]);

  return flash;
}

/** The value from the previous render - handy for diffing feed snapshots. */
export function usePrevious<T>(value: T): T | undefined {
  const ref = useRef<T | undefined>(undefined);
  useEffect(() => {
    ref.current = value;
  }, [value]);
  return ref.current;
}

/**
 * requestAnimationFrame loop that stays mounted across re-renders. Used by the
 * mock feed and by chart crosshair redraws; `fps` throttles it.
 */
export function useAnimationFrame(callback: (dt: number) => void, fps = 60) {
  const cb = useRef(callback);
  cb.current = callback;

  useEffect(() => {
    if (fps <= 0) return;
    let raf = 0;
    let last = performance.now();
    const minDelta = 1000 / fps;

    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = now - last;
      if (dt < minDelta) return;
      last = now;
      cb.current(dt);
    };

    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [fps]);
}

/** True when the user has asked the OS to reduce motion. */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof matchMedia !== 'function') return;
    const mq = matchMedia('(prefers-reduced-motion: reduce)');
    setReduced(mq.matches);
    const onChange = (e: MediaQueryListEvent) => setReduced(e.matches);
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, []);
  return reduced;
}

'use client';

import {
  createContext,
  useContext,
  useMemo,
  type CSSProperties,
  type ReactNode,
} from 'react';
import { TooltipProvider } from '../components/ui/tooltip';
import type { Instrument } from '../types';
import { cn } from '../utils';

export type ThemeName = 'dark' | 'light';
export type DirectionPalette = 'classic' | 'colorblind';

export interface TradingTheme {
  theme: ThemeName;
  /** `classic` is green/red; `colorblind` is blue/amber. */
  palette: DirectionPalette;
  /** Formatting defaults for components not given their own instrument. */
  instrument: Instrument;
}

export const defaultInstrument: Instrument = {
  symbol: '',
  pricePrecision: 2,
  tickSize: 0.01,
  sizePrecision: 0,
  currency: '$',
};

const ThemeContext = createContext<TradingTheme>({
  theme: 'dark',
  palette: 'classic',
  instrument: defaultInstrument,
});

export function useTradingTheme(): TradingTheme {
  return useContext(ThemeContext);
}

/**
 * Resolves the instrument a component formats with: its own prop wins, then
 * the provider's, then the library default.
 */
export function useInstrument(override?: Partial<Instrument>): Instrument {
  const { instrument } = useTradingTheme();
  return useMemo(
    () => (override ? { ...instrument, ...override } : instrument),
    [instrument, override],
  );
}

export interface TradingProviderProps {
  children: ReactNode;
  theme?: ThemeName;
  palette?: DirectionPalette;
  instrument?: Partial<Instrument>;
  /** Token overrides, e.g. `{ '--primary': '#ff8a00' }`. */
  tokens?: Record<string, string>;
  /**
   * Skip the wrapper element and inherit whatever theme the host already
   * applies. Use this inside an existing shadcn app that owns `.dark` itself.
   */
  inherit?: boolean;
  className?: string;
  style?: CSSProperties;
}

/**
 * Scopes theme, direction palette and instrument defaults to a subtree.
 *
 * Deliberately not a global stylesheet switch: two providers can coexist, so a
 * light-themed report can sit inside a dark terminal. Also mounts a single
 * Radix TooltipProvider so every tooltip in the tree shares one delay timer.
 */
export function TradingProvider({
  children,
  theme = 'dark',
  palette = 'classic',
  instrument,
  tokens,
  inherit = false,
  className,
  style,
}: TradingProviderProps) {
  const value = useMemo<TradingTheme>(
    () => ({ theme, palette, instrument: { ...defaultInstrument, ...instrument } }),
    [theme, palette, instrument],
  );

  const content = <TooltipProvider>{children}</TooltipProvider>;

  return (
    <ThemeContext.Provider value={value}>
      {inherit ? (
        content
      ) : (
        <div
          data-tu-theme={theme}
          data-tu-palette={palette}
          className={cn(
            'bg-background text-foreground',
            theme === 'dark' && 'dark',
            className,
          )}
          style={{ ...(tokens as CSSProperties | undefined), ...style }}
        >
          {content}
        </div>
      )}
    </ThemeContext.Provider>
  );
}

import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

/**
 * Merge Tailwind classes with later ones winning - the same `cn` shadcn/ui
 * uses, so a consumer can override any class on any component by passing
 * `className`, with no specificity war.
 */
export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/** Shared empty array, so a normalized-away prop keeps a stable identity and
 *  does not invalidate the `useMemo` that depends on it on every render. */
const EMPTY: readonly never[] = Object.freeze([]);

/**
 * Coerces a feed-supplied collection to something safe to iterate.
 *
 * A live feed is not a type system. Sockets drop fields, REST returns `null`
 * for "no rows yet", and a panel mounts before its first payload lands. None
 * of that should unmount the React tree — a component with nothing to show
 * renders its empty state instead. Returns a frozen shared array when the
 * input is unusable, so the identity stays stable across renders.
 */
export function toArray<T>(value: readonly T[] | null | undefined): readonly T[] {
  return Array.isArray(value) ? value : (EMPTY as readonly T[]);
}

/** `toArray` for both sides of a book, tolerating a missing snapshot entirely. */
export function toBook<T>(book: { bids?: readonly T[] | null; asks?: readonly T[] | null } | null | undefined) {
  return { bids: toArray(book?.bids), asks: toArray(book?.asks) };
}
